CREATE TABLE departments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, manager_name VARCHAR(120) NOT NULL, areas JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, initials VARCHAR(4) NOT NULL, department_id INT UNSIGNED NULL, role_name VARCHAR(120) NOT NULL, manager_name VARCHAR(120) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_users_department FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_name VARCHAR(160) NOT NULL, event_type VARCHAR(60) NOT NULL, event_date DATE NOT NULL, event_time TIME NOT NULL, venue VARCHAR(160) NOT NULL, guest_count SMALLINT UNSIGNED NOT NULL, commercial_owner VARCHAR(120) NOT NULL, amount DECIMAL(12,2) NULL, budget_file VARCHAR(255) NULL, status VARCHAR(50) NOT NULL DEFAULT 'Orçamento aprovado', preparation_percent TINYINT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_events_date (event_date)) ENGINE=InnoDB;
CREATE TABLE tasks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, department_id INT UNSIGNED NULL, assignee_id INT UNSIGNED NULL, event_id INT UNSIGNED NULL, validator_name VARCHAR(120) NULL, priority ENUM('Alta','Média','Baixa') NOT NULL DEFAULT 'Média', status ENUM('A fazer','Em andamento','Em validação','Concluída','Bloqueada') NOT NULL DEFAULT 'A fazer', due_at DATETIME NOT NULL, description TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL, CONSTRAINT fk_tasks_department FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL, CONSTRAINT fk_tasks_assignee FOREIGN KEY (assignee_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_tasks_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL, INDEX idx_tasks_status_due (status, due_at)) ENGINE=InnoDB;
